using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    // Technical details that must not leak into business code.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.Net", "System.IO", "System.Data", "System.Diagnostics.Process", "Microsoft.Data",
        "Microsoft.EntityFrameworkCore", "Microsoft.Extensions.Http", "Newtonsoft.Json",
    ];

    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly Infrastructure = typeof(HttpPaymentGateway).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_outer_layers()
        => AssertNone(Types.InAssembly(Domain).ShouldNot().HaveDependencyOnAny(ApplicationNs, InfrastructureNs));

    [Fact]
    public void Application_does_not_depend_on_Infrastructure()
        => AssertNone(Types.InAssembly(Application).ShouldNot().HaveDependencyOn(InfrastructureNs));

    [Fact]
    public void Domain_does_not_use_technical_details()
        => AssertNone(Types.InAssembly(Domain).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    [Fact]
    public void Application_does_not_use_technical_details()
        => AssertNone(Types.InAssembly(Application).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    [Fact]
    public void Assemblies_reference_only_allowed_layers()
    {
        Assert.DoesNotContain(Domain.GetReferencedAssemblies(), a => a.Name!.StartsWith("PaymentAuthorization."));
        Assert.DoesNotContain(Application.GetReferencedAssemblies(), a => a.Name == Infrastructure.GetName().Name);
    }

    private static void AssertNone(ConditionList rule)
    {
        var result = rule.GetResult();
        Assert.True(result.IsSuccessful, "Layer violations: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
